export const getApiOrganizationsNameSettingsRepositoriesRoute = createRoute({
  method: 'get',
  path: '/api/organizations/{name}/settings/repositories',
  tags: ['orgs'],
  summary: 'List organization repositories',
  request: {
    params: z.object({
      name: z
        .string()
        .openapi({
          param: { name: 'name', in: 'path', required: true, schema: { type: 'string' } },
        }),
    }),
    query: z.object({
      search: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'search',
            in: 'query',
            schema: {
              description: 'Filter repositories by name (case-insensitive substring match)',
              type: 'string',
            },
            required: false,
          },
          description: 'Filter repositories by name (case-insensitive substring match)',
        }),
      type: z
        .enum(['dataset', 'model', 'space', 'bucket', 'kernel', 'container'])
        .exactOptional()
        .openapi({
          param: {
            name: 'type',
            in: 'query',
            schema: {
              description: 'Filter by repository type',
              type: 'string',
              enum: ['dataset', 'model', 'space', 'bucket', 'kernel', 'container'],
            },
            required: false,
          },
          description: 'Filter by repository type',
        }),
      limit: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int().min(1).max(9007199254740991),
        )
        .exactOptional()
        .openapi({
          param: {
            name: 'limit',
            in: 'query',
            schema: {
              description: 'Max number of repositories to return',
              type: 'integer',
              minimum: 1,
              maximum: 9007199254740991,
            },
            required: false,
          },
          description: 'Max number of repositories to return',
        }),
      sort: z
        .enum(['storage', 'updatedAt'])
        .default('storage')
        .exactOptional()
        .openapi({
          param: {
            name: 'sort',
            in: 'query',
            schema: {
              default: 'storage',
              description: 'Sort field (default: storage)',
              type: 'string',
              enum: ['storage', 'updatedAt'],
            },
            required: false,
          },
          description: 'Sort field (default: storage)',
        }),
      direction: z
        .enum(['asc', 'desc'])
        .default('desc')
        .exactOptional()
        .openapi({
          param: {
            name: 'direction',
            in: 'query',
            schema: {
              default: 'desc',
              description: 'Sort direction (default: desc)',
              type: 'string',
              enum: ['asc', 'desc'],
            },
            required: false,
          },
          description: 'Sort direction (default: desc)',
        }),
    }),
  },
  responses: {
    200: {
      description: 'Organization repositories with storage usage',
      content: {
        'application/json': {
          schema: z
            .array(
              z
                .strictObject({
                  id: z.string(),
                  type: z.enum(['dataset', 'model', 'space', 'bucket', 'kernel', 'container']),
                  updatedAt: z.string(),
                  visibility: z.enum(['public', 'private', 'protected']),
                  storage: z.number(),
                  storagePercent: z.number(),
                })
                .openapi({
                  required: ['id', 'type', 'updatedAt', 'visibility', 'storage', 'storagePercent'],
                }),
            )
            .openapi({ $schema: 'https://json-schema.org/draft/2020-12/schema' }),
        },
      },
    },
  },
})

export const putApiOrganizationsNameSettingsSsoCredentialsRoute = createRoute({
  method: 'put',
  path: '/api/organizations/{name}/settings/sso/credentials',
  tags: ['orgs'],
  summary: 'Rotate SSO credentials',
  description:
    "Update SSO credentials of the organization's SSO configuration. SSO stays enabled and does not need to be re-tested, so rotation causes no downtime. Requires a paid plan.",
  request: {
    params: z.object({
      name: z
        .string()
        .openapi({
          param: { name: 'name', in: 'path', required: true, schema: { type: 'string' } },
        }),
    }),
    body: {
      content: {
        'application/json': {
          schema: z
            .union([
              z
                .object({ clientSecret: z.string().min(1).max(1024) })
                .openapi({ required: ['clientSecret'], description: 'OIDC client secret' }),
              z
                .object({ x509Cert: z.string().min(1).max(10000) })
                .openapi({ required: ['x509Cert'], description: 'SAML IdP x509 certificate' }),
            ])
            .openapi({ $schema: 'https://json-schema.org/draft/2020-12/schema' }),
        },
      },
    },
  },
  responses: {
    200: {
      description: 'The SSO credentials were rotated',
      content: {
        'application/json': {
          schema: z.any().openapi({ $schema: 'https://json-schema.org/draft/2020-12/schema' }),
        },
      },
    },
  },
})

