export const postApiOrganizationsNameServiceAccountsServiceAccountIdTokensRoute = createRoute({
  method: 'post',
  path: '/api/organizations/{name}/service-accounts/{serviceAccountId}/tokens',
  tags: ['service-accounts'],
  summary: 'Create service-account token',
  description:
    'Create a new access token for a service account. Store the token securely - it cannot be retrieved later.',
  request: {
    params: z.object({
      name: z
        .string()
        .openapi({
          param: { name: 'name', in: 'path', required: true, schema: { type: 'string' } },
        }),
      serviceAccountId: z
        .string()
        .openapi({
          param: {
            name: 'serviceAccountId',
            in: 'path',
            required: true,
            schema: { type: 'string' },
          },
        }),
    }),
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              displayName: z
                .string()
                .min(1)
                .max(100)
                .default('API Token')
                .exactOptional()
                .openapi({ description: 'Display name for the token' }),
              permissions: z
                .array(
                  z.enum([
                    'repo.content.read',
                    'repo.contribute.write',
                    'repo.write',
                    'inference.serverless.write',
                    'inference.endpoints.infer.write',
                    'inference.endpoints.write',
                    'org.read',
                    'org.write',
                    'collection.read',
                    'collection.write',
                    'resourceGroup.write',
                    'job.write',
                    'org.serviceAccounts.read',
                    'org.serviceAccounts.write',
                    'org.auditLog.write',
                  ]),
                )
                .default([])
                .exactOptional()
                .openapi({ description: 'Org-wide permissions for this token' }),
              repoIds: z
                .array(
                  z
                    .string()
                    .regex(/^[0-9a-fA-F]{24}$/)
                    .length(24),
                )
                .exactOptional()
                .openapi({
                  description:
                    'Repositories to grant `repoPermissions` on. Can be repositories owned by the organization or any public repository. These override the org-wide permissions.',
                }),
              repoPermissions: z
                .array(z.enum(['repo.content.read', 'repo.write']))
                .default([])
                .exactOptional()
                .openapi({ description: 'Permissions granted on the selected `repoIds`.' }),
              endpointPatterns: z
                .array(
                  z
                    .string()
                    .regex(/^[^.?()\]\\[{}]+$/)
                    .max(256),
                )
                .max(20)
                .default([])
                .exactOptional()
                .openapi({
                  description:
                    "Inference endpoint name patterns (wildcards allowed, e.g. `gpt2-*`) restricting the token's org-wide Inference Endpoint permissions to matching endpoints. Empty means all endpoints.",
                }),
              skipNetworkSecurity: z
                .boolean()
                .default(false)
                .exactOptional()
                .openapi({
                  description:
                    "Exempt this token from the org's Network Security enforcement (IP allowlist and content access policy). Enterprise Plus only, and requires the `org.networkSecurity.write` permission.",
                }),
            })
            .openapi({ $schema: 'https://json-schema.org/draft/2020-12/schema', required: [] }),
        },
      },
    },
  },
  responses: {
    201: {
      description: 'Created token',
      content: {
        'application/json': {
          schema: z
            .strictObject({
              token: z
                .string()
                .openapi({
                  description:
                    'The access token - store this securely, it cannot be retrieved later',
                }),
              tokenInfo: z
                .strictObject({
                  _id: z.string(),
                  displayName: z.string(),
                  createdAt: z.string(),
                  permissions: z.array(z.string()).exactOptional(),
                  repoIds: z.array(z.string()),
                  repoPermissions: z.array(z.string()),
                  endpointPatterns: z.array(z.string()),
                  skipNetworkSecurity: z.boolean(),
                })
                .openapi({
                  required: [
                    '_id',
                    'displayName',
                    'createdAt',
                    'repoIds',
                    'repoPermissions',
                    'endpointPatterns',
                    'skipNetworkSecurity',
                  ],
                }),
            })
            .openapi({
              $schema: 'https://json-schema.org/draft/2020-12/schema',
              required: ['token', 'tokenInfo'],
            }),
        },
      },
    },
  },
})

