export const patchApiOrganizationsNameServiceAccountsServiceAccountIdTokensTokenIdRoute =
  createRoute({
    method: 'patch',
    path: '/api/organizations/{name}/service-accounts/{serviceAccountId}/tokens/{tokenId}',
    tags: ['service-accounts'],
    summary: 'Update service-account token',
    description: 'Update the name and/or permissions of an existing service account token.',
    request: {
      params: z.object({
        name: z
          .string()
          .openapi({
            param: { name: 'name', in: 'path', required: true, schema: { type: 'string' } },
          }),
        serviceAccountId: z
          .string()
          .openapi({
            param: {
              name: 'serviceAccountId',
              in: 'path',
              required: true,
              schema: { type: 'string' },
            },
          }),
        tokenId: z
          .string()
          .openapi({
            param: { name: 'tokenId', in: 'path', required: true, schema: { type: 'string' } },
          }),
      }),
      body: {
        content: {
          'application/json': {
            schema: z
              .object({
                displayName: z
                  .string()
                  .min(1)
                  .max(100)
                  .exactOptional()
                  .openapi({ description: 'New display name for the token' }),
                permissions: z
                  .array(
                    z.enum([
                      'repo.content.read',
                      'repo.contribute.write',
                      'repo.write',
                      'inference.serverless.write',
                      'inference.endpoints.infer.write',
                      'inference.endpoints.write',
                      'org.read',
                      'org.write',
                      'collection.read',
                      'collection.write',
                      'resourceGroup.write',
                      'job.write',
                      'org.serviceAccounts.read',
                      'org.serviceAccounts.write',
                      'org.auditLog.write',
                    ]),
                  )
                  .exactOptional()
                  .openapi({ description: 'Org-wide permissions for this token' }),
                repoIds: z
                  .array(
                    z
                      .string()
                      .regex(/^[0-9a-fA-F]{24}$/)
                      .length(24),
                  )
                  .exactOptional()
                  .openapi({
                    description:
                      'Repositories to grant `repoPermissions` on. Can be repositories owned by the organization or any public repository. These override the org-wide permissions.',
                  }),
                repoPermissions: z
                  .array(z.enum(['repo.content.read', 'repo.write']))
                  .exactOptional()
                  .openapi({ description: 'Permissions granted on the selected `repoIds`.' }),
                endpointPatterns: z
                  .array(
                    z
                      .string()
                      .regex(/^[^.?()\]\\[{}]+$/)
                      .max(256),
                  )
                  .max(20)
                  .exactOptional()
                  .openapi({
                    description:
                      "Inference endpoint name patterns (wildcards allowed, e.g. `gpt2-*`) restricting the token's org-wide Inference Endpoint permissions to matching endpoints. Empty means all endpoints.",
                  }),
                skipNetworkSecurity: z
                  .boolean()
                  .exactOptional()
                  .openapi({
                    description:
                      "Exempt this token from the org's Network Security enforcement (IP allowlist and content access policy). Enterprise Plus only, and requires the `org.networkSecurity.write` permission.",
                  }),
              })
              .openapi({ $schema: 'https://json-schema.org/draft/2020-12/schema', required: [] }),
          },
        },
      },
    },
    responses: {
      200: {
        description: 'Updated token info',
        content: {
          'application/json': {
            schema: z
              .strictObject({
                _id: z.string(),
                displayName: z.string(),
                permissions: z.array(z.string()),
                repoIds: z.array(z.string()),
                repoPermissions: z.array(z.string()),
                endpointPatterns: z.array(z.string()),
                skipNetworkSecurity: z.boolean(),
              })
              .openapi({
                $schema: 'https://json-schema.org/draft/2020-12/schema',
                required: [
                  '_id',
                  'displayName',
                  'permissions',
                  'repoIds',
                  'repoPermissions',
                  'endpointPatterns',
                  'skipNetworkSecurity',
                ],
              }),
          },
        },
      },
    },
  })

