export const getApiOrganizationsNameMembersRoute = createRoute({
  method: 'get',
  path: '/api/organizations/{name}/members',
  tags: ['orgs'],
  summary: 'Get organization members',
  description: 'Get a list of members for the organization with optional search and pagination.',
  request: {
    params: z.object({
      name: z
        .string()
        .openapi({
          param: { name: 'name', in: 'path', required: true, schema: { type: 'string' } },
        }),
    }),
    query: z.object({
      search: z
        .string()
        .exactOptional()
        .openapi({
          param: { name: 'search', in: 'query', schema: { type: 'string' }, required: false },
        }),
      email: z
        .email()
        .regex(
          /^(?:[A-Za-z0-9_'+\-]+\.)*[A-Za-z0-9_'+\-]*[A-Za-z0-9_+-]@(?:[A-Za-z0-9][A-Za-z0-9\-]*\.)+[A-Za-z]{2,}$/,
        )
        .exactOptional()
        .openapi({
          param: {
            name: 'email',
            in: 'query',
            schema: {
              type: 'string',
              format: 'email',
              pattern:
                "^(?:[A-Za-z0-9_'+\\-]+\\.)*[A-Za-z0-9_'+\\-]*[A-Za-z0-9_+-]@(?:[A-Za-z0-9][A-Za-z0-9\\-]*\\.)+[A-Za-z]{2,}$",
            },
            required: false,
          },
        }),
      cursor: z
        .string()
        .exactOptional()
        .openapi({
          param: { name: 'cursor', in: 'query', schema: { type: 'string' }, required: false },
        }),
      limit: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int().min(10).max(10000),
        )
        .default(500)
        .exactOptional()
        .openapi({
          param: {
            name: 'limit',
            in: 'query',
            schema: { default: 500, type: 'integer', minimum: 10, maximum: 10000 },
            required: false,
          },
        }),
      includeExternal: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'includeExternal',
            in: 'query',
            schema: {
              description: 'Include external collaborators. Only honored for org admins.',
              type: 'string',
            },
            required: false,
          },
          description: 'Include external collaborators. Only honored for org admins.',
        }),
    }),
  },
  responses: {
    200: {
      description: 'Array of organization members',
      content: {
        'application/json': {
          schema: z
            .array(
              z
                .strictObject({
                  avatarUrl: z.string(),
                  fullname: z.string(),
                  isPro: z.boolean(),
                  user: z.string(),
                  type: z.literal('user'),
                  isFollowing: z.boolean().exactOptional(),
                  _id: z
                    .string()
                    .regex(/^[0-9a-f]{24}$/)
                    .length(24)
                    .openapi({
                      description: 'A hex string of 24 characters representing an ObjectId.',
                    }),
                  role: z
                    .enum(['admin', 'write', 'contributor', 'read', 'no_access'])
                    .exactOptional(),
                  resourceGroups: z
                    .array(
                      z
                        .strictObject({
                          name: z.string(),
                          id: z.string(),
                          numUsers: z.number(),
                          role: z.enum(['admin', 'write', 'contributor', 'read', 'no_access']),
                          assignedRole: z.enum([
                            'admin',
                            'write',
                            'contributor',
                            'read',
                            'no_access',
                            'inherit',
                          ]),
                        })
                        .openapi({ required: ['name', 'id', 'numUsers', 'role', 'assignedRole'] }),
                    )
                    .exactOptional(),
                  twoFaEnabled: z.boolean().exactOptional(),
                  verifiedEmail: z
                    .string()
                    .nullable()
                    .exactOptional()
                    .openapi({
                      description:
                        "The user's SSO email, if the org has a Team or Enterprise plan and the requester is an admin",
                    }),
                  isExternalCollaborator: z.boolean().exactOptional(),
                })
                .openapi({ required: ['avatarUrl', 'fullname', 'isPro', 'user', 'type', '_id'] }),
            )
            .openapi({ $schema: 'https://json-schema.org/draft/2020-12/schema' }),
        },
      },
      headers: z.object({
        Link: {
          description: 'Link header for pagination, can contain a `rel="next"` link',
          schema: z
            .string()
            .exactOptional()
            .openapi({
              description: 'Link header for pagination, can contain a `rel="next"` link',
              param: { required: false },
              $schema: 'https://json-schema.org/draft/2020-12/schema',
            }),
        },
      }),
    },
  },
})

