export const getOauthUserinfoRoute = createRoute({
  method: 'get',
  path: '/oauth/userinfo',
  tags: ['oauth'],
  summary: 'Get user info',
  description:
    'Get information about the user. Only available through oauth access tokens. Information varies depending on the scope of the oauth app and what permissions the user granted to the oauth app.',
  responses: {
    200: {
      description: 'User info',
      content: {
        'application/json': {
          schema: z
            .strictObject({
              sub: z.string().openapi({ description: 'ID of the user' }),
              name: z.string().exactOptional().openapi({ description: 'Full name of the user' }),
              preferred_username: z
                .string()
                .exactOptional()
                .openapi({ description: 'Username of the user' }),
              profile: z.url().exactOptional().openapi({ description: 'Profile URL of the user' }),
              picture: z.url().exactOptional().openapi({ description: 'Avatar URL of the user' }),
              website: z.url().exactOptional().openapi({ description: 'Website of the user' }),
              email: z.string().exactOptional().openapi({ description: 'Email of the user' }),
              email_verified: z
                .boolean()
                .exactOptional()
                .openapi({ description: 'Whether the email is verified' }),
              hardwareItems: z
                .array(
                  z
                    .strictObject({
                      sku: z
                        .array(z.unknown())
                        .superRefine((arr, ctx) => {
                          const Prefix = [z.string(), z.string(), z.string()]
                          for (const [i, Schema] of Prefix.slice(0, arr.length).entries()) {
                            const result = Schema.safeParse(arr[i])
                            if (!result.success) {
                              for (const issue of result.error.issues) {
                                ctx.addIssue({ ...issue, path: [i, ...issue.path] })
                              }
                            }
                          }
                          for (let i = Prefix.length; i < arr.length; i++) {
                            ctx.addIssue({ code: 'custom', path: [i] })
                          }
                        })
                        .length(3)
                        .openapi({ description: 'Hardware SKU as [type, vendor, model]' }),
                      mem: z.number().openapi({ description: 'Memory in GB' }),
                      num: z.number().openapi({ description: 'Number of units' }),
                      isPrimary: z.literal(true).exactOptional(),
                    })
                    .openapi({ required: ['sku', 'mem', 'num'] }),
                )
                .exactOptional()
                .openapi({
                  description:
                    "The user's hardware items, if the `profile` scope is granted and the user did not set them as private",
                }),
              isPro: z.boolean().openapi({ description: 'Whether the user is a Pro user' }),
              canPay: z
                .boolean()
                .exactOptional()
                .openapi({
                  description:
                    'Whether the user has access to billing. You should check `canPay` first.',
                }),
              billingMode: z
                .enum(['prepaid', 'postpaid'])
                .exactOptional()
                .openapi({ description: 'Whether the user is on prepaid or postpaid billing' }),
              groups: z
                .array(z.string())
                .openapi({
                  description:
                    'Names of the organizations the user belongs to, as a list of strings for OIDC clients syncing groups from a claim',
                }),
              orgs: z.array(
                z
                  .strictObject({
                    sub: z.string().openapi({ description: 'ID of the organization' }),
                    name: z.string().openapi({ description: 'Name of the organization' }),
                    picture: z.url().openapi({ description: 'Avatar URL of the organization' }),
                    preferred_username: z
                      .string()
                      .openapi({ description: 'Username of the organization' }),
                    plan: z.enum(['team', 'enterprise', 'plus', 'academia']).exactOptional(),
                    canPay: z.boolean().exactOptional(),
                    billingMode: z.enum(['prepaid', 'postpaid']).exactOptional(),
                    roleInOrg: z
                      .enum(['admin', 'write', 'contributor', 'read', 'no_access'])
                      .exactOptional(),
                    securityRestrictions: z
                      .array(z.enum(['mfa', 'token-policy', 'token-revoked', 'sso', 'ip']))
                      .exactOptional()
                      .openapi({
                        description:
                          'Current security restrictions for accessing data in this organization with current authentication method',
                      }),
                    resourceGroups: z
                      .array(
                        z
                          .strictObject({
                            sub: z.string(),
                            name: z.string(),
                            role: z.enum(['admin', 'write', 'contributor', 'read', 'no_access']),
                          })
                          .openapi({ required: ['sub', 'name', 'role'] }),
                      )
                      .exactOptional(),
                  })
                  .openapi({ required: ['sub', 'name', 'picture', 'preferred_username'] }),
              ),
            })
            .openapi({
              $schema: 'https://json-schema.org/draft/2020-12/schema',
              required: ['sub', 'isPro', 'groups', 'orgs'],
            }),
        },
      },
    },
  },
})

