export const getApiRegistryTokenRoute = createRoute({
  method: 'get',
  path: '/api/registry/token',
  tags: ['containers'],
  summary: 'Registry token',
  description:
    'Mints a short-lived EdDSA JWT for the HuggingFace container registry, verifiable via the JWK at `/api/keys/jwt`.',
  request: {
    query: z.object({
      service: z
        .string()
        .min(1)
        .openapi({
          param: {
            name: 'service',
            in: 'query',
            schema: {
              type: 'string',
              minLength: 1,
              description: 'Registry service identifier — placed in the JWT `aud` claim.',
            },
            required: true,
          },
          description: 'Registry service identifier — placed in the JWT `aud` claim.',
        }),
      scope: z
        .union([z.string(), z.array(z.string())])
        .exactOptional()
        .openapi({
          param: {
            name: 'scope',
            in: 'query',
            schema: {
              description:
                'Docker Distribution scope(s), e.g. `repository:org/img:push,pull`. May be repeated.',
              anyOf: [{ type: 'string' }, { type: 'array', items: { type: 'string' } }],
            },
            required: false,
          },
          description:
            'Docker Distribution scope(s), e.g. `repository:org/img:push,pull`. May be repeated.',
        }),
    }),
  },
  responses: {
    200: {
      description:
        'Docker Distribution v2 token response — see https://distribution.github.io/distribution/spec/auth/jwt/',
      content: {
        'application/json': {
          schema: z
            .strictObject({
              token: z
                .string()
                .openapi({
                  description: 'EdDSA JWT signed by the moon JWT key, carrying `access[]`.',
                }),
              access_token: z
                .string()
                .openapi({
                  description:
                    'Identical to `token` — Docker Distribution v2 accepts either field.',
                }),
              expires_in: z
                .int()
                .min(-9007199254740991)
                .max(9007199254740991)
                .openapi({ description: 'JWT lifetime in seconds.' }),
              issued_at: z.iso
                .datetime({ offset: true })
                .regex(
                  /^(?:(?:\d\d[2468][048]|\d\d[13579][26]|\d\d0[48]|[02468][048]00|[13579][26]00)-02-29|\d{4}-(?:(?:0[13578]|1[02])-(?:0[1-9]|[12]\d|3[01])|(?:0[469]|11)-(?:0[1-9]|[12]\d|30)|(?:02)-(?:0[1-9]|1\d|2[0-8])))T(?:(?:[01]\d|2[0-3]):[0-5]\d:[0-5]\d(?:\.\d+)?(?:Z))$/,
                )
                .openapi({ description: 'ISO-8601 timestamp at which the JWT was minted.' }),
            })
            .openapi({
              $schema: 'https://json-schema.org/draft/2020-12/schema',
              required: ['token', 'access_token', 'expires_in', 'issued_at'],
            }),
        },
      },
    },
  },
})

