export const postApiBlogNamespaceSlugResourceGroupRoute = createRoute({
  method: 'post',
  path: '/api/blog/{namespace}/{slug}/resource-group',
  tags: ['blogs'],
  summary: 'Blog resource group',
  description:
    'Assign, move, or unassign an organization-owned blog to a resource group. Pass null to unassign. User-owned blogs are not eligible.',
  request: {
    params: z.object({
      namespace: z
        .string()
        .openapi({
          param: { name: 'namespace', in: 'path', required: true, schema: { type: 'string' } },
        }),
      slug: z
        .string()
        .openapi({
          param: { name: 'slug', in: 'path', required: true, schema: { type: 'string' } },
        }),
    }),
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              resourceGroupId: z
                .union([
                  z
                    .string()
                    .regex(/^[0-9a-fA-F]{24}$/)
                    .length(24),
                  z.null().nullable(),
                ])
                .openapi({
                  description:
                    'The resource group to assign the blog to. If null, the blog is removed from any resource group.',
                }),
            })
            .openapi({
              $schema: 'https://json-schema.org/draft/2020-12/schema',
              required: ['resourceGroupId'],
            }),
        },
      },
    },
  },
  responses: {
    200: {
      description: 'The blog and its resource group after the assignment',
      content: {
        'application/json': {
          schema: z
            .strictObject({
              resourceGroupId: z.union([
                z
                  .string()
                  .regex(/^[0-9a-f]{24}$/)
                  .length(24)
                  .openapi({
                    description: 'A hex string of 24 characters representing an ObjectId.',
                  }),
                z.null().nullable(),
              ]),
              id: z
                .string()
                .regex(/^[0-9a-f]{24}$/)
                .length(24)
                .openapi({
                  description: 'A hex string of 24 characters representing an ObjectId.',
                }),
              slug: z.string(),
              title: z.string(),
              private: z.boolean(),
              addedBy: z.string(),
            })
            .openapi({
              $schema: 'https://json-schema.org/draft/2020-12/schema',
              required: ['resourceGroupId', 'id', 'slug', 'title', 'private', 'addedBy'],
            }),
        },
      },
    },
  },
})

