export const getApiUsersUsernameOverviewRoute = createRoute({
  method: 'get',
  path: '/api/users/{username}/overview',
  tags: ['users'],
  summary: 'User overview',
  request: {
    params: z.object({
      username: z
        .string()
        .openapi({
          param: { name: 'username', in: 'path', required: true, schema: { type: 'string' } },
        }),
    }),
  },
  responses: {
    200: {
      description: 'User overview data including their organizations, stats, and creation date',
      content: {
        'application/json': {
          schema: z
            .strictObject({
              _id: z
                .string()
                .regex(/^[0-9a-f]{24}$/)
                .length(24)
                .openapi({
                  description: 'A hex string of 24 characters representing an ObjectId.',
                }),
              orgs: z
                .array(
                  z
                    .strictObject({
                      id: z.string(),
                      name: z.string(),
                      fullname: z.string(),
                      avatarUrl: z.string(),
                    })
                    .openapi({ required: ['id', 'name', 'fullname', 'avatarUrl'] }),
                )
                .exactOptional(),
              avatarUrl: z.string(),
              fullname: z.string(),
              isPro: z.boolean(),
              user: z.string(),
              numModels: z.number().exactOptional(),
              numDatasets: z.number().exactOptional(),
              numSpaces: z.number().exactOptional(),
              numBuckets: z.number().exactOptional(),
              numKernels: z.number().exactOptional(),
              numDiscussions: z.number().exactOptional(),
              numPapers: z.number().exactOptional(),
              numUpvotes: z.number().exactOptional(),
              numLikes: z.number().exactOptional(),
              numFollowers: z.number().exactOptional(),
              numFollowing: z.number().exactOptional(),
              numFollowingOrgs: z.number().exactOptional(),
              details: z.string().exactOptional(),
              isFollowing: z.boolean().exactOptional(),
              reasonToFollow: z.string().exactOptional(),
              primaryOrgAvatarUrl: z.string().exactOptional(),
              serviceAccount: z
                .strictObject({
                  id: z
                    .string()
                    .regex(/^[0-9a-f]{24}$/)
                    .length(24)
                    .openapi({
                      description: 'A hex string of 24 characters representing an ObjectId.',
                    }),
                  org: z.string(),
                  orgAvatarUrl: z.string(),
                  description: z.string().exactOptional(),
                })
                .exactOptional()
                .openapi({
                  description: 'Set when the user is a service account',
                  required: ['id', 'org', 'orgAvatarUrl'],
                }),
              type: z.literal('user'),
              createdAt: z.iso
                .datetime({ offset: true })
                .regex(
                  /^(?:(?:\d\d[2468][048]|\d\d[13579][26]|\d\d0[48]|[02468][048]00|[13579][26]00)-02-29|\d{4}-(?:(?:0[13578]|1[02])-(?:0[1-9]|[12]\d|3[01])|(?:0[469]|11)-(?:0[1-9]|[12]\d|30)|(?:02)-(?:0[1-9]|1\d|2[0-8])))T(?:(?:[01]\d|2[0-3]):[0-5]\d:[0-5]\d(?:\.\d+)?(?:Z))$/,
                ),
              hardwareItems: z
                .array(
                  z
                    .strictObject({
                      sku: z
                        .array(z.unknown())
                        .superRefine((arr, ctx) => {
                          const Prefix = [z.string(), z.string(), z.string()]
                          for (const [i, Schema] of Prefix.slice(0, arr.length).entries()) {
                            const result = Schema.safeParse(arr[i])
                            if (!result.success) {
                              for (const issue of result.error.issues) {
                                ctx.addIssue({ ...issue, path: [i, ...issue.path] })
                              }
                            }
                          }
                          for (let i = Prefix.length; i < arr.length; i++) {
                            ctx.addIssue({ code: 'custom', path: [i] })
                          }
                        })
                        .length(3)
                        .openapi({ description: 'Hardware SKU as [type, vendor, model]' }),
                      mem: z.number().openapi({ description: 'Memory in GB' }),
                      num: z.number().openapi({ description: 'Number of units' }),
                      isPrimary: z.literal(true).exactOptional(),
                    })
                    .openapi({ required: ['sku', 'mem', 'num'] }),
                )
                .exactOptional()
                .openapi({
                  description: "The user's hardware items, unless the user set them as private",
                }),
            })
            .openapi({
              $schema: 'https://json-schema.org/draft/2020-12/schema',
              required: ['_id', 'avatarUrl', 'fullname', 'isPro', 'user', 'type', 'createdAt'],
            }),
        },
      },
    },
  },
})

