export const getApiModelsNamespaceRepoTreesizeRevPathRoute = createRoute({
  method: 'get',
  path: '/api/models/{namespace}/{repo}/treesize/{rev}/{path}',
  tags: ['models'],
  summary: 'Get folder size',
  description:
    'Get the total size of a repository at a given revision, optionally under a specific subpath. Returns the total size in bytes of all files under the specified path (recursively). If a file is stored via Xet/LFS, the LFS file size is used.',
  request: {
    params: z.object({
      namespace: z
        .string()
        .openapi({
          param: { name: 'namespace', in: 'path', required: true, schema: { type: 'string' } },
        }),
      repo: z
        .string()
        .openapi({
          param: { name: 'repo', in: 'path', required: true, schema: { type: 'string' } },
        }),
      rev: z
        .string()
        .openapi({
          param: { name: 'rev', in: 'path', required: true, schema: { type: 'string' } },
        }),
      path: z
        .string()
        .openapi({
          param: {
            name: 'path',
            in: 'path',
            required: true,
            schema: { type: 'string', description: 'Wildcard path parameter' },
          },
          description: 'Wildcard path parameter',
        }),
    }),
  },
  responses: {
    200: {
      description: 'Total size of a repository at a given revision, under the given path',
      content: {
        'application/json': {
          schema: z
            .strictObject({
              path: z
                .string()
                .openapi({
                  description: 'The normalized path of the subtree, starting with a slash',
                }),
              size: z
                .int()
                .min(-9007199254740991)
                .max(9007199254740991)
                .openapi({ description: 'Total size in bytes of all files under the subtree' }),
            })
            .openapi({
              $schema: 'https://json-schema.org/draft/2020-12/schema',
              required: ['path', 'size'],
            }),
        },
      },
    },
  },
})

