export const getApiModelsNamespaceRepoSafetensorsMetadataPathRoute = createRoute({
  method: 'get',
  path: '/api/models/{namespace}/{repo}/safetensors-metadata/{path}',
  tags: ['models'],
  summary: 'Get safetensors metadata',
  description:
    "Get the parsed headers of all the shards of a sharded safetensors model in a single request, instead of reading the index and then the header of every shard.\n\nOnly the `main` revision is served: the `ETag` is the commit sha of `main`, and requests with a matching `If-None-Match` get a 304. Returns 400 when the path isn't a `.safetensors.index.json` file and 422 when the files can't be parsed.\n\nThe response is brotli-compressed when the client accepts it, otherwise gzip-compressed or plain JSON.",
  request: {
    params: z.object({
      namespace: z
        .string()
        .openapi({
          param: { name: 'namespace', in: 'path', required: true, schema: { type: 'string' } },
        }),
      repo: z
        .string()
        .openapi({
          param: { name: 'repo', in: 'path', required: true, schema: { type: 'string' } },
        }),
      path: z
        .string()
        .openapi({
          param: {
            name: 'path',
            in: 'path',
            required: true,
            schema: { type: 'string', description: 'Wildcard path parameter' },
          },
          description: 'Wildcard path parameter',
        }),
    }),
  },
  responses: {
    200: {
      description: 'Parsed headers of the shards of a sharded safetensors model',
      content: {
        'application/json': {
          schema: z
            .strictObject({
              sharded: z.literal(true),
              index: z
                .strictObject({
                  metadata: z.record(z.string(), z.union([z.string(), z.number()])).exactOptional(),
                })
                .openapi({
                  description:
                    'The index file, without its `weight_map`: each shard header lists its tensors',
                  required: [],
                }),
              headers: z
                .record(
                  z.string(),
                  z.record(
                    z.string(),
                    z.union([
                      z
                        .strictObject({
                          dtype: z.string(),
                          shape: z.array(z.int().min(-9007199254740991).max(9007199254740991)),
                          data_offsets: z
                            .array(z.unknown())
                            .superRefine((arr, ctx) => {
                              const Prefix = [
                                z.int().min(-9007199254740991).max(9007199254740991),
                                z.int().min(-9007199254740991).max(9007199254740991),
                              ]
                              for (const [i, Schema] of Prefix.slice(0, arr.length).entries()) {
                                const result = Schema.safeParse(arr[i])
                                if (!result.success) {
                                  for (const issue of result.error.issues) {
                                    ctx.addIssue({ ...issue, path: [i, ...issue.path] })
                                  }
                                }
                              }
                              for (let i = Prefix.length; i < arr.length; i++) {
                                ctx.addIssue({ code: 'custom', path: [i] })
                              }
                            })
                            .length(2),
                        })
                        .openapi({ required: ['dtype', 'shape', 'data_offsets'] }),
                      z.record(z.string(), z.string()),
                    ]),
                  ),
                )
                .openapi({
                  description:
                    'The header of each shard, by shard file name: `__metadata__`, then the `dtype`, `shape` and `data_offsets` of each tensor',
                }),
              parameterCount: z
                .record(z.string(), z.int().min(-9007199254740991).max(9007199254740991))
                .openapi({ description: 'Number of parameters per dtype' }),
              parameterTotal: z.int().min(-9007199254740991).max(9007199254740991).exactOptional(),
              filepaths: z
                .array(z.string())
                .openapi({ description: 'The index file, then every shard file' }),
            })
            .openapi({
              $schema: 'https://json-schema.org/draft/2020-12/schema',
              required: ['sharded', 'index', 'headers', 'parameterCount', 'filepaths'],
            }),
        },
      },
    },
  },
})

