export const postApiModelsNamespaceRepoPreuploadRevRoute = createRoute({
  method: 'post',
  path: '/api/models/{namespace}/{repo}/preupload/{rev}',
  tags: ['models'],
  summary: 'Check upload method',
  description: 'Check if a file should be uploaded through the Large File mechanism or directly.',
  request: {
    params: z.object({
      namespace: z
        .string()
        .openapi({
          param: { name: 'namespace', in: 'path', required: true, schema: { type: 'string' } },
        }),
      repo: z
        .string()
        .openapi({
          param: { name: 'repo', in: 'path', required: true, schema: { type: 'string' } },
        }),
      rev: z
        .string()
        .openapi({
          param: { name: 'rev', in: 'path', required: true, schema: { type: 'string' } },
        }),
    }),
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              files: z
                .array(
                  z
                    .object({ path: z.string(), size: z.number(), sample: z.string() })
                    .openapi({ required: ['path', 'size', 'sample'] }),
                )
                .max(1000),
              gitAttributes: z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    'Provide this parameter if you plan to modify `.gitattributes` yourself at the same time as uploading LFS files. Note that this is not needed if you solely rely on automatic LFS detection from HF: the commit endpoint will automatically edit the `.gitattributes` file to track the files passed to its `lfsFiles` param.',
                }),
              gitIgnore: z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    'Content of the .gitignore file for the revision. Optional, otherwise takes the existing content of `.gitignore` for the revision.',
                }),
            })
            .openapi({
              $schema: 'https://json-schema.org/draft/2020-12/schema',
              required: ['files'],
            }),
        },
      },
    },
  },
  responses: {
    200: {
      description: 'Files to be uploaded.',
      content: {
        'application/json': {
          schema: z
            .strictObject({
              files: z.array(
                z
                  .strictObject({
                    path: z.string(),
                    uploadMode: z.enum(['lfs', 'regular']),
                    shouldIgnore: z.boolean(),
                    oid: z
                      .string()
                      .exactOptional()
                      .openapi({
                        description:
                          "The oid of the blob if it already exists in the repository. If the blob is a LFS file, it'll be the lfs oid.",
                      }),
                  })
                  .openapi({ required: ['path', 'uploadMode', 'shouldIgnore'] }),
              ),
              commitOid: z.string(),
            })
            .openapi({
              $schema: 'https://json-schema.org/draft/2020-12/schema',
              required: ['files', 'commitOid'],
            }),
        },
      },
    },
    422: {
      description: 'The request is invalid',
      content: {
        'application/json': {
          schema: z.any().openapi({ $schema: 'https://json-schema.org/draft/2020-12/schema' }),
        },
      },
    },
  },
})

