export const postApiModelsNamespaceRepoCommitRevRoute = createRoute({
  method: 'post',
  path: '/api/models/{namespace}/{repo}/commit/{rev}',
  tags: ['models'],
  summary: 'Commit',
  description:
    'For legacy reason, we support both `application/json` and `application/x-ndjson` but we recommend using `application/x-ndjson` to create a commit.\n\nJSON-lines payload:\n```json\n{\n  "key": "header",\n  "value": {\n    "summary": "string (REQUIRED)",\n    "description": "string (OPTIONAL - defaults to empty string)",\n    "parentCommit": "string (OPTIONAL - 40-character hex SHA)"\n  }\n}\n{\n  "key": "file",\n  "value": {\n    "path": "string (REQUIRED)",\n    "content": "string (OPTIONAL - required if oldPath not set)",\n    "encoding": "utf-8 | base64 (OPTIONAL - defaults to utf-8)",\n    "oldPath": "string (OPTIONAL - for move/rename operations)"\n  }\n}\n{\n  "key": "deletedEntry",\n  "value": {\n    "path": "string (REQUIRED)"\n  }\n}\n{\n  "key": "lfsFile",\n  "value": {\n    "path": "string (REQUIRED - max 1000 chars)",\n    "oid": "string (OPTIONAL - required if oldPath not set, 64 hex chars)",\n    "algo": "sha256 (OPTIONAL - only sha256 supported)",\n    "size": "number (OPTIONAL - required if oldPath is set)",\n    "oldPath": "string (OPTIONAL - for move/rename operations)"\n  }\n}\n```\n\nJSON payload:\n```json\n{\n  "summary": "string (REQUIRED)",\n  "description": "string (OPTIONAL - defaults to empty string)",\n  "parentCommit": "string (OPTIONAL - 40-character hex SHA)"\n  "files": [\n    {\n      "path": "string (REQUIRED)",\n      "content": "string (OPTIONAL - required if oldPath not set)",\n      "encoding": "utf-8 | base64 (OPTIONAL - defaults to utf-8)",\n      "oldPath": "string (OPTIONAL - for move/rename operations)"\n    }\n  ],\n  "deletedEntries": [\n    {\n      "path": "string (REQUIRED)"\n    }\n  ],\n  "lfsFiles": [\n    {\n      "path": "string (REQUIRED - max 1000 chars)",\n      "oid": "string (OPTIONAL - required if oldPath not set, 64 hex chars)",\n      "algo": "sha256 (OPTIONAL - only sha256 supported)",\n      "size": "number (OPTIONAL - required if oldPath is set)",\n      "oldPath": "string (OPTIONAL - for move/rename operations)"\n    }\n  ]\n}\n```\n',
  request: {
    params: z.object({
      namespace: z
        .string()
        .openapi({
          param: { name: 'namespace', in: 'path', required: true, schema: { type: 'string' } },
        }),
      repo: z
        .string()
        .openapi({
          param: { name: 'repo', in: 'path', required: true, schema: { type: 'string' } },
        }),
      rev: z
        .string()
        .openapi({
          param: { name: 'rev', in: 'path', required: true, schema: { type: 'string' } },
        }),
    }),
    query: z.object({
      create_pr: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'create_pr',
            in: 'query',
            schema: {
              description: 'Whether to create a pull request from the commit',
              type: 'string',
            },
            required: false,
          },
          description: 'Whether to create a pull request from the commit',
        }),
      hot_reload: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'hot_reload',
            in: 'query',
            schema: {
              description:
                'For Spaces, whether to try to hot reload the commit (only for single python files updates)',
              type: 'string',
            },
            required: false,
          },
          description:
            'For Spaces, whether to try to hot reload the commit (only for single python files updates)',
        }),
    }),
    headers: z.object({
      'Content-Type': z
        .enum(['application/json', 'application/x-ndjson'])
        .default('application/x-ndjson')
        .exactOptional()
        .openapi({
          param: {
            name: 'Content-Type',
            in: 'header',
            schema: {
              $schema: 'https://json-schema.org/draft/2020-12/schema',
              default: 'application/x-ndjson',
              description: '`application/x-ndjson` if you to commit by json lines',
              type: 'string',
              enum: ['application/json', 'application/x-ndjson'],
            },
            required: false,
          },
          $schema: 'https://json-schema.org/draft/2020-12/schema',
          description: '`application/x-ndjson` if you to commit by json lines',
        }),
    }),
  },
  responses: {
    200: {
      description: 'The response of the commit',
      content: {
        'application/json': {
          schema: z
            .strictObject({
              success: z.boolean().openapi({ description: 'Whether the commit was successful' }),
              pullRequestUrl: z
                .string()
                .exactOptional()
                .openapi({ description: 'The URL of the pull request' }),
              commitOid: z.string().openapi({ description: 'The OID of the commit' }),
              commitUrl: z.string().openapi({ description: 'The URL of the commit' }),
              hookOutput: z.string().openapi({ description: 'The output of the git hook' }),
            })
            .openapi({
              $schema: 'https://json-schema.org/draft/2020-12/schema',
              required: ['success', 'commitOid', 'commitUrl', 'hookOutput'],
            }),
        },
      },
    },
  },
})

