export const getApiModelsNamespaceRepoJwtRoute = createRoute({
  method: 'get',
  path: '/api/models/{namespace}/{repo}/jwt',
  tags: ['models'],
  summary: 'Generate JWT',
  description:
    'Generate a JWT token for accessing a repository. Supports optional write access for spaces in dev mode, custom expiration, and encryption.',
  request: {
    params: z.object({
      namespace: z
        .string()
        .openapi({
          param: { name: 'namespace', in: 'path', required: true, schema: { type: 'string' } },
        }),
      repo: z
        .string()
        .openapi({
          param: { name: 'repo', in: 'path', required: true, schema: { type: 'string' } },
        }),
    }),
    query: z.object({
      write: z
        .string()
        .exactOptional()
        .openapi({
          param: { name: 'write', in: 'query', schema: { type: 'string' }, required: false },
        }),
      expiration: z.iso
        .datetime({ offset: true })
        .regex(
          /^(?:(?:\d\d[2468][048]|\d\d[13579][26]|\d\d0[48]|[02468][048]00|[13579][26]00)-02-29|\d{4}-(?:(?:0[13578]|1[02])-(?:0[1-9]|[12]\d|3[01])|(?:0[469]|11)-(?:0[1-9]|[12]\d|30)|(?:02)-(?:0[1-9]|1\d|2[0-8])))T(?:(?:[01]\d|2[0-3]):[0-5]\d:[0-5]\d(?:\.\d+)?(?:Z))$/,
        )
        .exactOptional()
        .openapi({
          param: {
            name: 'expiration',
            in: 'query',
            schema: {
              description:
                'Requested expiration datetime, capped at the default (10 minutes with write, 24 hours for spaces, 1 hour otherwise). Use expires_in instead.',
              deprecated: true,
              type: 'string',
              format: 'date-time',
              pattern:
                '^(?:(?:\\d\\d[2468][048]|\\d\\d[13579][26]|\\d\\d0[48]|[02468][048]00|[13579][26]00)-02-29|\\d{4}-(?:(?:0[13578]|1[02])-(?:0[1-9]|[12]\\d|3[01])|(?:0[469]|11)-(?:0[1-9]|[12]\\d|30)|(?:02)-(?:0[1-9]|1\\d|2[0-8])))T(?:(?:[01]\\d|2[0-3]):[0-5]\\d:[0-5]\\d(?:\\.\\d+)?(?:Z))$',
            },
            required: false,
          },
          description:
            'Requested expiration datetime, capped at the default (10 minutes with write, 24 hours for spaces, 1 hour otherwise). Use expires_in instead.',
          deprecated: true,
        }),
      expires_in: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int().min(60).max(86400),
        )
        .exactOptional()
        .openapi({
          param: {
            name: 'expires_in',
            in: 'query',
            schema: {
              description:
                'Requested lifetime in seconds, capped at the default (600s with write, 86400s for spaces, 3600s otherwise)',
              type: 'integer',
              minimum: 60,
              maximum: 86400,
            },
            required: false,
          },
          description:
            'Requested lifetime in seconds, capped at the default (600s with write, 86400s for spaces, 3600s otherwise)',
        }),
      encrypted: z
        .string()
        .exactOptional()
        .openapi({
          param: { name: 'encrypted', in: 'query', schema: { type: 'string' }, required: false },
        }),
      inference_api: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'inference_api',
            in: 'query',
            schema: { type: 'string' },
            required: false,
          },
        }),
      include_pro_status: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'include_pro_status',
            in: 'query',
            schema: {
              deprecated: true,
              description: 'Use billing_details instead.',
              type: 'string',
            },
            required: false,
          },
          deprecated: true,
          description: 'Use billing_details instead.',
        }),
      billing_details: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'billing_details',
            in: 'query',
            schema: { type: 'string' },
            required: false,
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'The JWT token and related information',
      content: {
        'application/json': {
          schema: z
            .strictObject({
              accessToken: z.string().openapi({ description: 'The JWT token with Bearer prefix' }),
              exp: z
                .int()
                .min(-9007199254740991)
                .max(9007199254740991)
                .exactOptional()
                .openapi({ description: 'Token expiration timestamp in seconds (JWT standard)' }),
              token: z.string().openapi({ description: 'The JWT token' }),
              encryptedToken: z
                .strictObject({
                  encrypted: z.string().openapi({ description: 'The encrypted JWT token' }),
                  keyId: z.string().openapi({ description: 'Key ID used to encrypt the token' }),
                })
                .exactOptional()
                .openapi({
                  description:
                    'Encrypted JWT token and key ID (only if encrypted=true was requested)',
                  required: ['encrypted', 'keyId'],
                }),
            })
            .openapi({
              $schema: 'https://json-schema.org/draft/2020-12/schema',
              required: ['accessToken', 'token'],
            }),
        },
      },
    },
  },
})

