export const getApiAgentHarnessesRoute = createRoute({
  method: 'get',
  path: '/api/agent-harnesses',
  tags: ['agents'],
  summary: 'Get agent harnesses',
  description:
    'Get the registry of AI agents / harnesses known to the Hub, along with the standard environment variables used to detect them. Clients use this registry to identify which agent they are running in when reporting Hub activity.',
  responses: {
    200: {
      description: 'The registry of AI agents / harnesses known to the Hub',
      content: {
        'application/json': {
          schema: z
            .strictObject({
              standardEnvVars: z
                .array(z.string())
                .openapi({
                  description:
                    'Standard environment variables that any agent can set to identify itself. Their value is matched against the harness ids.',
                }),
              harnesses: z
                .record(
                  z.string(),
                  z
                    .strictObject({
                      prettyLabel: z
                        .string()
                        .openapi({ description: 'Human-readable name of the harness' }),
                      repoUrl: z
                        .string()
                        .exactOptional()
                        .openapi({ description: "URL to the harness's code repository" }),
                      docsUrl: z
                        .string()
                        .exactOptional()
                        .openapi({ description: "URL to the harness's documentation or website" }),
                      description: z
                        .string()
                        .exactOptional()
                        .openapi({ description: 'Short description of the harness' }),
                      envVars: z
                        .record(z.string(), z.string())
                        .exactOptional()
                        .openapi({
                          description:
                            'Environment variable(s) identifying this harness, mapped to the value pattern they must match: "*" (set to any non-empty value), an exact value, or a "<prefix>*" fuzzy match. Detection matches if ANY entry matches.',
                        }),
                    })
                    .openapi({ required: ['prettyLabel'] }),
                )
                .openapi({
                  description:
                    'Registered harnesses, keyed by id and ordered by detection priority: the first match wins',
                }),
            })
            .openapi({
              $schema: 'https://json-schema.org/draft/2020-12/schema',
              required: ['standardEnvVars', 'harnesses'],
            }),
        },
      },
    },
  },
})

export const getApiModelsTagsByTypeRoute = createRoute({
  method: 'get',
  path: '/api/models-tags-by-type',
  tags: ['models'],
  summary: 'Get model tags',
  description:
    'Get all possible tags used for models, grouped by tag type. Optionally restrict to only one tag type',
  request: {
    query: z.object({
      type: z
        .enum([
          'pipeline_tag',
          'library',
          'dataset',
          'bucket',
          'language',
          'license',
          'arxiv',
          'doi',
          'region',
          'deploy',
          'other',
        ])
        .exactOptional()
        .openapi({
          param: {
            name: 'type',
            in: 'query',
            schema: {
              type: 'string',
              enum: [
                'pipeline_tag',
                'library',
                'dataset',
                'bucket',
                'language',
                'license',
                'arxiv',
                'doi',
                'region',
                'deploy',
                'other',
              ],
            },
            required: false,
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'The tags, grouped by tag type',
      content: {
        'application/json': {
          schema: z
            .record(
              z.string(),
              z.array(
                z
                  .strictObject({
                    id: z.string(),
                    label: z.string(),
                    type: z.enum([
                      'pipeline_tag',
                      'library',
                      'dataset',
                      'bucket',
                      'language',
                      'license',
                      'arxiv',
                      'doi',
                      'region',
                      'deploy',
                      'other',
                    ]),
                    subType: z.string().exactOptional(),
                    clickable: z.boolean().default(true).exactOptional(),
                  })
                  .openapi({ required: ['id', 'label', 'type'] }),
              ),
            )
            .superRefine((o, ctx) => {
              const allowed = [
                'pipeline_tag',
                'library',
                'dataset',
                'bucket',
                'language',
                'license',
                'arxiv',
                'doi',
                'region',
                'deploy',
                'other',
              ]
              for (const k of Object.keys(o)) {
                if (!allowed.includes(k)) {
                  ctx.addIssue({ code: 'custom', path: [k] })
                }
              }
            })
            .openapi({ $schema: 'https://json-schema.org/draft/2020-12/schema' }),
        },
      },
    },
  },
})

