export const postApiRepoTypeNamespaceRepoDuplicateRoute = createRoute({
  method: 'post',
  path: '/api/{repoType}/{namespace}/{repo}/duplicate',
  tags: ['repos'],
  summary: 'Duplicate a repository',
  request: {
    params: z.object({
      repoType: z
        .literal('spaces')
        .openapi({
          param: {
            name: 'repoType',
            in: 'path',
            required: true,
            schema: { type: 'string', enum: ['spaces'] },
          },
        }),
      namespace: z
        .string()
        .openapi({
          param: { name: 'namespace', in: 'path', required: true, schema: { type: 'string' } },
        }),
      repo: z
        .string()
        .openapi({
          param: { name: 'repo', in: 'path', required: true, schema: { type: 'string' } },
        }),
    }),
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              repository: z.string(),
              private: z.boolean().exactOptional(),
              visibility: z.enum(['private', 'public', 'protected']).exactOptional(),
              resourceGroupId: z
                .union([
                  z
                    .string()
                    .regex(/^[0-9a-fA-F]{24}$/)
                    .length(24),
                  z.null().nullable(),
                ])
                .exactOptional(),
              hardware: z
                .enum([
                  'cpu-basic',
                  'cpu-upgrade',
                  'cpu-performance',
                  'cpu-xl',
                  'sprx8',
                  'zero-a10g',
                  't4-small',
                  't4-medium',
                  'l4x1',
                  'l4x4',
                  'l40sx1',
                  'l40sx4',
                  'l40sx8',
                  'a10g-small',
                  'a10g-large',
                  'a10g-largex2',
                  'a10g-largex4',
                  'a100-large',
                  'a100x4',
                  'a100x8',
                  'h200',
                  'h200x2',
                  'h200x4',
                  'h200x8',
                  'rtx-pro-6000',
                  'rtx-pro-6000x2',
                  'rtx-pro-6000x4',
                  'rtx-pro-6000x8',
                  'inf2x6',
                  '',
                ])
                .default('')
                .exactOptional(),
              sleepTimeSeconds: z
                .union([z.int().gt(0).max(9007199254740991), z.literal(-1)])
                .exactOptional(),
              secrets: z
                .array(
                  z
                    .object({
                      key: z.string().regex(/^[a-zA-Z][_a-zA-Z0-9]*$/),
                      description: z.string().exactOptional(),
                      value: z.string(),
                    })
                    .openapi({ required: ['key', 'value'] }),
                )
                .default([])
                .exactOptional(),
              variables: z
                .array(
                  z
                    .object({
                      key: z.string().regex(/^[a-zA-Z][_a-zA-Z0-9]*$/),
                      description: z.string().exactOptional(),
                      value: z.string(),
                    })
                    .openapi({ required: ['key', 'value'] }),
                )
                .default([])
                .exactOptional(),
              volumes: z
                .array(
                  z
                    .object({
                      type: z.enum(['bucket', 'model', 'dataset', 'space']),
                      source: z
                        .string()
                        .openapi({
                          description:
                            "Source identifier, e.g. 'username/my-bucket' or 'username/my-model'",
                        }),
                      mountPath: z
                        .string()
                        .regex(/^\/.*/)
                        .openapi({ description: "Mount path inside the container, e.g. '/data'" }),
                      revision: z
                        .string()
                        .exactOptional()
                        .openapi({
                          description: "Git revision (only for repos, defaults to 'main')",
                        }),
                      readOnly: z
                        .boolean()
                        .exactOptional()
                        .openapi({
                          description:
                            'Read-only mount (true for repos, false default for buckets)',
                        }),
                      path: z
                        .string()
                        .exactOptional()
                        .openapi({
                          description:
                            "Subfolder prefix inside the bucket/repo to mount, e.g. 'path/to/dir'",
                        }),
                    })
                    .openapi({ required: ['type', 'source', 'mountPath'] }),
                )
                .exactOptional()
                .openapi({
                  description:
                    'HuggingFace Buckets or Repos to mount as volumes in the duplicated Space.',
                }),
            })
            .openapi({
              $schema: 'https://json-schema.org/draft/2020-12/schema',
              required: ['repository'],
            }),
        },
      },
    },
  },
  responses: {
    200: {
      description: 'Repository created, url is given',
      content: {
        'application/json': {
          schema: z
            .strictObject({
              url: z.string(),
              filesCopyPending: z
                .boolean()
                .openapi({
                  description:
                    "True when the repo's LFS/Xet files are still being copied in the background; poll `…/duplicate/status`",
                }),
            })
            .openapi({
              $schema: 'https://json-schema.org/draft/2020-12/schema',
              required: ['url', 'filesCopyPending'],
            }),
        },
      },
    },
  },
})

export const getApiRepoTypeNamespaceRepoDuplicateStatusRoute = createRoute({
  method: 'get',
  path: '/api/{repoType}/{namespace}/{repo}/duplicate/status',
  tags: ['repos'],
  summary: 'Duplication status',
  request: {
    params: z.object({
      repoType: z
        .enum(['models', 'datasets', 'spaces'])
        .openapi({
          param: {
            name: 'repoType',
            in: 'path',
            required: true,
            schema: { type: 'string', enum: ['models', 'datasets', 'spaces'] },
          },
        }),
      namespace: z
        .string()
        .openapi({
          param: { name: 'namespace', in: 'path', required: true, schema: { type: 'string' } },
        }),
      repo: z
        .string()
        .openapi({
          param: { name: 'repo', in: 'path', required: true, schema: { type: 'string' } },
        }),
    }),
  },
  responses: {
    200: {
      description: 'Progress of the background LFS/Xet copy of a duplicated repository',
      content: {
        'application/json': {
          schema: z
            .strictObject({
              pending: z
                .boolean()
                .openapi({ description: 'True while the LFS/Xet files are still being copied' }),
              filesTotal: z
                .int()
                .min(-9007199254740991)
                .max(9007199254740991)
                .exactOptional()
                .openapi({ description: 'Number of LFS/Xet files the duplicate references' }),
              filesCopied: z
                .int()
                .min(-9007199254740991)
                .max(9007199254740991)
                .exactOptional()
                .openapi({ description: 'Number of files copied so far' }),
            })
            .openapi({
              $schema: 'https://json-schema.org/draft/2020-12/schema',
              required: ['pending'],
            }),
        },
      },
    },
  },
})

