export const postApiModelsNamespaceRepoUserAccessRequestBatchRoute = createRoute({
  method: 'post',
  path: '/api/models/{namespace}/{repo}/user-access-request/batch',
  tags: ['models'],
  summary: 'Batch access requests',
  description:
    'Accept, reject, reset or set back to pending up to 100 access requests for a single gated repository in one call. The same `status` (and optional `rejectionReason` or `resetReason`) is applied to every request in the list.',
  request: {
    params: z.object({
      namespace: z
        .string()
        .openapi({
          param: { name: 'namespace', in: 'path', required: true, schema: { type: 'string' } },
        }),
      repo: z
        .string()
        .openapi({
          param: { name: 'repo', in: 'path', required: true, schema: { type: 'string' } },
        }),
    }),
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              status: z.enum(['accepted', 'rejected', 'pending', 'reset']),
              rejectionReason: z.string().max(200).exactOptional(),
              resetReason: z.string().max(200).exactOptional(),
              requests: z
                .array(
                  z.xor([
                    z
                      .object({
                        requestId: z
                          .string()
                          .regex(/^[0-9a-fA-F]{24}$/)
                          .length(24)
                          .openapi({
                            description:
                              "Id of the request as returned by the listing endpoint; the only identifier when the requester's profile is not shared",
                          }),
                      })
                      .openapi({ required: ['requestId'] }),
                    z
                      .object({
                        userId: z
                          .string()
                          .regex(/^[0-9a-fA-F]{24}$/)
                          .length(24),
                      })
                      .openapi({ required: ['userId'] }),
                    z.object({ user: z.string() }).openapi({ required: ['user'] }),
                  ]),
                )
                .min(1)
                .max(100),
            })
            .openapi({
              $schema: 'https://json-schema.org/draft/2020-12/schema',
              required: ['status', 'requests'],
            }),
        },
      },
    },
  },
  responses: {
    200: {
      description: 'Per-request outcomes, in the same order as the input requests array.',
      content: {
        'application/json': {
          schema: z
            .array(
              z
                .strictObject({
                  requestId: z.string().exactOptional(),
                  userId: z.string().exactOptional(),
                  user: z.string().exactOptional(),
                  ok: z.boolean(),
                  error: z.enum(['user_not_found', 'request_not_found']).exactOptional(),
                })
                .openapi({ required: ['ok'] }),
            )
            .openapi({ $schema: 'https://json-schema.org/draft/2020-12/schema' }),
        },
      },
    },
  },
})

