export const getApiPapersRoute = createRoute({
  method: 'get',
  path: '/api/papers',
  tags: ['papers'],
  summary: 'List papers',
  description: 'List arXiv papers sorted by published date',
  request: {
    query: z.object({
      cursor: z
        .base64()
        .transform((val, ctx) => {
          try {
            return JSON.parse(
              new TextDecoder().decode(Uint8Array.from(atob(val), (char) => char.charCodeAt(0))),
            )
          } catch (err) {
            ctx.addIssue({
              code: 'custom',
              params: { cause: err instanceof Error ? err.message : String(err) },
            })
            return z.NEVER
          }
        })
        .exactOptional()
        .openapi({
          param: {
            name: 'cursor',
            in: 'query',
            schema: {
              description: 'Pagination cursor',
              type: 'string',
              contentEncoding: 'base64',
              contentMediaType: 'application/json',
            },
            required: false,
          },
          description: 'Pagination cursor',
        }),
      limit: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int().min(1).max(100),
        )
        .default(50)
        .exactOptional()
        .openapi({
          param: {
            name: 'limit',
            in: 'query',
            schema: { default: 50, type: 'integer', minimum: 1, maximum: 100 },
            required: false,
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'List of papers',
      content: {
        'application/json': {
          schema: z
            .array(
              z
                .strictObject({
                  id: z.string(),
                  title: z.string(),
                  upvotes: z.number(),
                  publishedAt: z.iso
                    .datetime({ offset: true })
                    .regex(
                      /^(?:(?:\d\d[2468][048]|\d\d[13579][26]|\d\d0[48]|[02468][048]00|[13579][26]00)-02-29|\d{4}-(?:(?:0[13578]|1[02])-(?:0[1-9]|[12]\d|3[01])|(?:0[469]|11)-(?:0[1-9]|[12]\d|30)|(?:02)-(?:0[1-9]|1\d|2[0-8])))T(?:(?:[01]\d|2[0-3]):[0-5]\d:[0-5]\d(?:\.\d+)?(?:Z))$/,
                    ),
                  thumbnailUrl: z.string().exactOptional(),
                  authors: z.array(
                    z
                      .strictObject({
                        _id: z.string(),
                        name: z.string(),
                        status: z.string().exactOptional(),
                        statusLastChangedAt: z.iso
                          .datetime({ offset: true })
                          .regex(
                            /^(?:(?:\d\d[2468][048]|\d\d[13579][26]|\d\d0[48]|[02468][048]00|[13579][26]00)-02-29|\d{4}-(?:(?:0[13578]|1[02])-(?:0[1-9]|[12]\d|3[01])|(?:0[469]|11)-(?:0[1-9]|[12]\d|30)|(?:02)-(?:0[1-9]|1\d|2[0-8])))T(?:(?:[01]\d|2[0-3]):[0-5]\d:[0-5]\d(?:\.\d+)?(?:Z))$/,
                          )
                          .exactOptional(),
                        user: z
                          .strictObject({
                            _id: z.string(),
                            avatarUrl: z.string(),
                            fullname: z.string(),
                            isPro: z.boolean(),
                            name: z.string(),
                            type: z.string(),
                            user: z.string().exactOptional(),
                            isHf: z.boolean().exactOptional(),
                            isHfAdmin: z.boolean().exactOptional(),
                            isMod: z.boolean().exactOptional(),
                            followerCount: z.number().exactOptional(),
                          })
                          .exactOptional()
                          .openapi({
                            required: ['_id', 'avatarUrl', 'fullname', 'isPro', 'name', 'type'],
                            description: 'User overview information',
                          }),
                        hidden: z.boolean(),
                      })
                      .openapi({
                        required: ['_id', 'name', 'hidden'],
                        description: 'Paper author information',
                      }),
                  ),
                  summary: z.string(),
                  projectPage: z.string().exactOptional(),
                  githubRepo: z.string().exactOptional(),
                  ai_summary: z.string().exactOptional(),
                  organization: z
                    .strictObject({
                      _id: z.string(),
                      name: z.string(),
                      fullname: z.string().exactOptional(),
                      avatar: z.string().exactOptional(),
                    })
                    .exactOptional()
                    .openapi({ required: ['_id', 'name'] }),
                })
                .openapi({
                  required: ['id', 'title', 'upvotes', 'publishedAt', 'authors', 'summary'],
                }),
            )
            .openapi({ $schema: 'https://json-schema.org/draft/2020-12/schema' }),
        },
      },
    },
  },
})

export const postApiPapersIndexRoute = createRoute({
  method: 'post',
  path: '/api/papers/index',
  tags: ['papers'],
  summary: 'Index a paper',
  description:
    'Index a paper from arXiv by its ID. If the paper is already indexed, only its authors can re-index it.',
  request: {
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              arxivId: z
                .string()
                .regex(/^\d{4}\.\d{4,5}$/)
                .openapi({ description: 'The arXiv ID of the paper to index (e.g. 2301.00001)' }),
            })
            .openapi({
              $schema: 'https://json-schema.org/draft/2020-12/schema',
              required: ['arxivId'],
            }),
        },
      },
    },
  },
  responses: {
    200: {
      description: 'Empty object on success',
      content: {
        'application/json': {
          schema: z
            .strictObject({})
            .openapi({ $schema: 'https://json-schema.org/draft/2020-12/schema' }),
        },
      },
    },
  },
})

