export const postApiPapersPaperIdLinksRoute = createRoute({
  method: 'post',
  path: '/api/papers/{paperId}/links',
  tags: ['papers'],
  summary: 'Update paper links',
  description:
    'Update the project page, GitHub repository, or submitting organization for a paper. Requires the requester to be the paper author, the Daily Papers submitter, or a papers admin.',
  request: {
    params: z.object({
      paperId: z
        .string()
        .openapi({
          param: { name: 'paperId', in: 'path', required: true, schema: { type: 'string' } },
        }),
    }),
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              projectPage: z.union([z.url(), z.null().nullable()]).exactOptional(),
              githubRepo: z.union([z.url(), z.null().nullable()]).exactOptional(),
              organizationId: z
                .union([
                  z
                    .string()
                    .regex(/^[0-9a-fA-F]{24}$/)
                    .length(24),
                  z.null().nullable(),
                ])
                .exactOptional(),
            })
            .openapi({ $schema: 'https://json-schema.org/draft/2020-12/schema', required: [] }),
        },
      },
    },
  },
  responses: {
    200: {
      description: 'Paper links updated',
      content: {
        'application/json': {
          schema: z
            .strictObject({})
            .openapi({ $schema: 'https://json-schema.org/draft/2020-12/schema' }),
        },
      },
    },
  },
})

export const postApiPapersPaperIdMediaRoute = createRoute({
  method: 'post',
  path: '/api/papers/{paperId}/media',
  tags: ['papers'],
  summary: 'Update paper media',
  description:
    'Replace the media shown on a Daily Papers submission. Requires the requester to be the paper author, the Daily Papers submitter, or a papers admin.',
  request: {
    params: z.object({
      paperId: z
        .string()
        .openapi({
          param: { name: 'paperId', in: 'path', required: true, schema: { type: 'string' } },
        }),
    }),
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              mediaUrls: z
                .array(
                  z
                    .string()
                    .regex(
                      /(^https:\/\/s3\.amazonaws\.com\/hf-hub-cdn-uploads\/.*\.(gif|jpeg|jpg|mov|mp3|mp4|mpga|png|qt|wav|webm|webp)$)|(^https:\/\/cdn-uploads\.huggingface\.co\/.*\.(gif|jpeg|jpg|mov|mp3|mp4|mpga|png|qt|wav|webm|webp)$)/,
                    ),
                )
                .openapi({ description: 'Media URLs, in display order' }),
            })
            .openapi({
              $schema: 'https://json-schema.org/draft/2020-12/schema',
              required: ['mediaUrls'],
            }),
        },
      },
    },
  },
  responses: {
    200: {
      description: 'Paper media updated',
      content: {
        'application/json': {
          schema: z
            .strictObject({})
            .openapi({ $schema: 'https://json-schema.org/draft/2020-12/schema' }),
        },
      },
    },
  },
})

