export const postApiBucketsNamespaceRepoBatchRoute = createRoute({
  method: 'post',
  path: '/api/buckets/{namespace}/{repo}/batch',
  tags: ['buckets'],
  summary: 'Batch file operations',
  description:
    'Accepts NDJSON (newline-delimited JSON) where each line is an addFile, copyFile, or deleteFile instruction.\nAll add/copy operations must come before all delete operations.\n\nJSON-lines payload:\n```json\n\t\'{"type":"addFile","path":"...","xetHash":"...","mtime":...,"mtimeNanos":...,"contentType":"..."}\' +\n\t\'{"type":"copyFile","path":"...","xetHash":"...","sourceRepoType":"...","sourceRepoId":"...","mtime":...,"mtimeNanos":...,"contentType":"..."}\' +\n\t\'{"type":"deleteFile","path":"..."}\'\n```',
  request: {
    params: z.object({
      namespace: z
        .string()
        .openapi({
          param: { name: 'namespace', in: 'path', required: true, schema: { type: 'string' } },
        }),
      repo: z
        .string()
        .openapi({
          param: { name: 'repo', in: 'path', required: true, schema: { type: 'string' } },
        }),
    }),
  },
  responses: {
    200: {
      description: 'Batch operation status',
      content: {
        'application/json': {
          schema: z
            .strictObject({
              success: z.boolean().openapi({ description: 'True if all operations succeeded' }),
              processed: z
                .int()
                .min(-9007199254740991)
                .max(9007199254740991)
                .openapi({ description: 'Total number of operations attempted' }),
              succeeded: z
                .int()
                .min(-9007199254740991)
                .max(9007199254740991)
                .openapi({ description: 'Number of successful operations' }),
              failed: z
                .array(
                  z
                    .strictObject({
                      path: z.string().openapi({ description: 'File path that failed' }),
                      error: z.string().openapi({ description: 'Error message' }),
                    })
                    .openapi({ required: ['path', 'error'] }),
                )
                .openapi({ description: 'List of failed operations' }),
            })
            .openapi({
              $schema: 'https://json-schema.org/draft/2020-12/schema',
              required: ['success', 'processed', 'succeeded', 'failed'],
            }),
        },
      },
    },
    422: {
      description: 'Batch operation status',
      content: {
        'application/json': {
          schema: z
            .strictObject({
              success: z.boolean().openapi({ description: 'True if all operations succeeded' }),
              processed: z
                .int()
                .min(-9007199254740991)
                .max(9007199254740991)
                .openapi({ description: 'Total number of operations attempted' }),
              succeeded: z
                .int()
                .min(-9007199254740991)
                .max(9007199254740991)
                .openapi({ description: 'Number of successful operations' }),
              failed: z
                .array(
                  z
                    .strictObject({
                      path: z.string().openapi({ description: 'File path that failed' }),
                      error: z.string().openapi({ description: 'Error message' }),
                    })
                    .openapi({ required: ['path', 'error'] }),
                )
                .openapi({ description: 'List of failed operations' }),
            })
            .openapi({
              $schema: 'https://json-schema.org/draft/2020-12/schema',
              required: ['success', 'processed', 'succeeded', 'failed'],
            }),
        },
      },
    },
  },
})

