export const getApiJobsNamespaceCountRoute = createRoute({
  method: 'get',
  path: '/api/jobs/{namespace}/count',
  tags: ['jobs'],
  summary: 'Count jobs',
  description: 'Count the number of jobs for an entity with optional status stage filter',
  request: {
    params: z.object({
      namespace: z
        .string()
        .openapi({
          param: { name: 'namespace', in: 'path', required: true, schema: { type: 'string' } },
        }),
    }),
    query: z.object({
      stage: z
        .union([
          z.enum(['COMPLETED', 'CANCELED', 'ERROR', 'DELETED', 'RUNNING', 'SCHEDULING']),
          z.array(z.enum(['COMPLETED', 'CANCELED', 'ERROR', 'DELETED', 'RUNNING', 'SCHEDULING'])),
        ])
        .exactOptional()
        .openapi({
          param: {
            name: 'stage',
            in: 'query',
            schema: {
              anyOf: [
                {
                  type: 'string',
                  enum: ['COMPLETED', 'CANCELED', 'ERROR', 'DELETED', 'RUNNING', 'SCHEDULING'],
                },
                {
                  type: 'array',
                  items: {
                    type: 'string',
                    enum: ['COMPLETED', 'CANCELED', 'ERROR', 'DELETED', 'RUNNING', 'SCHEDULING'],
                  },
                },
              ],
            },
            required: false,
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'The count of jobs matching the filter',
      content: {
        'application/json': {
          schema: z
            .strictObject({ count: z.number() })
            .openapi({
              $schema: 'https://json-schema.org/draft/2020-12/schema',
              required: ['count'],
            }),
        },
      },
    },
  },
})

